body.query:
query ContactUsPage {
  resource(alias: "/contact-us") {
    __typename
    ... on Article {
      id
      title
      summary
      excerpt
      body
      primaryImage {
        ...ArticleBanner
      }
      createdAt
    }
  }
}

fragment ArticleBanner on AssetImage {
  description
  title
  file {
    url
    details {
      image {
        width
        height
      }
    }
    normal: thumbor(width: 1200, height: 500)
    mobile: thumbor(width: 800, height: 400)
  }
}
